<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import StatusBadge from '@/components/StatusBadge.vue'
import { useEmsStore } from '@/stores/ems'
const props = defineProps<{ section: 'strategies' | 'types' | 'issue' | 'schedule' | 'logs' | 'commands' }>()
const store = useEmsStore()
const modal = ref(false)
const editingId = ref('')
const keyword = ref('')
const pageSize = ref(8)
const currentPage = ref(1)
const selectedType = ref('削峰填谷')
const form = reactive({ name: '', type: '削峰填谷', priority: 1, power: '500.0 kW', targetSoc: '75.00%', schedule: '', trigger: '' })
const title = computed(() => ({ strategies: '策略管理', types: '策略类型', issue: '策略下发', schedule: '策略调度计划', logs: '策略执行日志', commands: '实时调度指令' }[props.section]))
const subtitle = computed(() => ({ strategies: '储能运行策略创建、编辑与版本维护', types: '储能调度策略类型与参数项', issue: '策略下发、暂停与停止控制', schedule: '周计划日历调度', logs: '策略执行记录与结果追踪', commands: '实时指令与近期策略调度详情' }[props.section]))
const filterText = (value: string) => value.toLowerCase().includes(keyword.value.trim().toLowerCase())
