  { name: '需量管理', desc: '基于15分钟平均功率预测，在需量越限前提前放电削峰', target: '降低最大需量电费', chargeWindow: '00:00-06:30', dischargeWindow: '08:30-11:30、14:00-17:30', chargePower: 420, dischargePower: 600, socMin: 35, socMax: 85, triggerPrice: 0.68, demandLimit: 1900, response: '5分钟滚动预测', curve: ['待机', '预充', '削峰放电', '待机', '削峰放电', '补电'], risk: '需保留备电SOC，避免过度削峰' },
  { name: '调频', desc: '按AGC或频率偏差快速充放电，限制SOC与爬坡率', target: '参与辅助服务并提升电网稳定性', chargeWindow: '全天可用', dischargeWindow: '全天可用', chargePower: 300, dischargePower: 300, socMin: 45, socMax: 75, triggerPrice: 0, demandLimit: 0, response: '秒级响应', curve: ['充电脉冲', '放电脉冲', '待机', '放电脉冲', '充电脉冲', '待机'], risk: '高频动作需监控PCS温度与循环次数' },
  { name: '防逆流', desc: '光伏大于负荷时提升充电功率，将并网点反向功率压到阈值内', target: '防止并网点反向送电', chargeWindow: '09:00-16:30', dischargeWindow: '18:00-21:00', chargePower: 480, dischargePower: 260, socMin: 30, socMax: 95, triggerPrice: 0, demandLimit: -30, response: '并网点实时闭环', curve: ['待机', '吸收光伏', '吸收光伏', '限充', '放电补偿', '待机'], risk: 'SOC接近上限时需切换限发策略' },
  { name: '离网备电', desc: '电网异常时切换离网供电，按负荷优先级释放储能', target: '保障关键负荷不断电', chargeWindow: '谷段保持备电SOC', dischargeWindow: '电网异常期间', chargePower: 500, dischargePower: 650, socMin: 50, socMax: 95, triggerPrice: 0, demandLimit: 0, response: '毫秒级切换', curve: ['备电保持', '备电保持', '离网放电', '负荷切除', '恢复并网', '补电'], risk: '需按负荷优先级切除非关键负荷' },
]
const currentType = computed(() => strategyTypes.find((item) => item.name === selectedType.value) || strategyTypes[0])
const weekDays = ['周一','周二','周三','周四','周五','周六','周日']
