e><article><label>响应方式</label><strong>{{ currentType.response }}</strong></article><article><label>风险控制</label><strong>{{ currentType.risk }}</strong></article></div></div></div></section>
    <section v-else-if="section === 'issue'" class="data-section span-12"><div class="query-bar"><el-input v-model="keyword" clearable placeholder="策略名称 / 类型" /><el-button type="primary">查询</el-button><el-button @click="keyword = ''">重置</el-button></div><el-table :data="strategyRows" stripe height="520"><el-table-column prop="name" label="策略"/><el-table-column label="状态"><template #default="{ row }"><StatusBadge :text="row.status" /></template></el-table-column><el-table-column prop="schedule" label="计划"/><el-table-column prop="trigger" label="触发条件"/><el-table-column label="操作" width="210"><template #default="{ row }"><el-button link type="primary" @click="store.issueStrategy(row.id)">下发执行</el-button><el-button link @click="store.updateStrategy(row.id, { status: '暂停' })">暂停</el-button><el-button link type="danger" @click="store.updateStrategy(row.id, { status: '停止' })">停止</el-button></template></el-table-column></el-table><div class="pager-row"><el-pagination v-model:current-page="currentPage" v-model:page-size="pageSize" :total="filteredStrategies.length" layout="total, sizes, prev, pager, next, jumper" /></div></section>
    <section v-else-if="section === 'schedule'" class="data-section span-12"><div class="week-calendar"><article v-for="day in weeklyPlans" :key="day.day" class="day-card"><strong>{{ day.day }}</strong><span v-for="plan in day.plans" :key="plan.name + plan.time" class="plan-chip">{{ plan.time }}<br />{{ plan.name }}<br />{{ plan.action }}</span></article></div></section>
    <section v-else-if="section === 'logs'" class="data-section span-12"><div class="query-bar"><el-input v-model="keyword" clearable placeholder="事件 / 结果" /><el-button type="primary">查询</el-button><el-button @click="keyword = ''">重置</el-button></div><el-table :data="logRows" stripe height="520"><el-table-column prop="time" label="时间"/><el-table-column prop="event" label="事件"/><el-table-column prop="result" label="执行结果"/></el-table><div class="pager-row"><el-pagination v-model:current-page="currentPage" v-model:page-size="pageSize" :total="store.logs.length" layout="total, sizes, prev, pager, next, jumper" /></div></section>
    <section v-else class="data-section span-12"><div class="detail-grid"><article><label>当前指令</label><strong>{{ store.snapshot.mode }}指令</strong></article><article><label>目标功率</label><strong>{{ store.format.kw(Math.abs(store.snapshot.storagePower)) }}</strong></article><article><label>当前SOC</label><strong>{{ store.format.pct(store.snapshot.soc) }}</strong></article><article><label>PCS响应</label><strong>闭环跟随正常，通讯延迟28ms</strong></article><article><label>更新时间</label><strong>{{ store.snapshot.timestamp }}</strong></article></div><h3>近期策略调度详情</h3><el-table :data="recentDispatch" stripe><el-table-column prop="time" label="时间" /><el-table-column prop="strategy" label="策略" /><el-table-column prop="command" label="指令" /><el-table-column prop="result" label="结果" /><el-table-column label="响应"><template #default="{ row }"><StatusBadge :text="row.response" /></template></el-table-column></el-table></section>
    <el-dialog v-model="modal" destroy-on-close class="ems-dialog" title="策略维护" width="680px"><el-form :model="form" label-width="90px"><el-form-item label="策略名称"><el-input v-model="form.name" /></el-form-item><el-form-item label="策略类型"><el-select v-model="form.type"><el-option v-for="item in strategyTypes" :key="item.name" :label="item.name" :value="item.name" /></el-select></el-form-item><el-form-item label="优先级"><el-input v-model.number="form.priority" type="number" /></el-form-item><el-form-item label="目标功率"><el-input v-model="form.power" /></el-form-item><el-form-item label="SOC目标"><el-input v-model="form.targetSoc" /></el-form-item><el-form-item label="调度计划"><el-input v-model="form.schedule" /></el-form-item><el-form-item label="触发条件"><el-input v-model="form.trigger" /></el-form-item></el-form><template #footer><el-button @click="modal = false">取消</el-button><el-button type="primary" @click="saveStrategy">保存</el-button></template></el-dialog>
  </div>
</template>
